123	async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
124	  await limiter.wait();
125	  const res = await fetch(url, { headers: { "User-Agent": "Nxeon/1.0 (mods@nxeon.cloud)" } });
126	  if ((res.status === 429 || res.status >= 500) && attempt <= 5) {
