151	function kebab(s: string): string {
152	  return s
153	    .toLowerCase()
154	    .replace(/[^a-z0-9]+/g, "-")
155	    .replace(/^-+|-+$/g, "")
156	    .slice(0, 60) || "workshop-item";
157	}
