164	async function fetchAuthors(limiter: RateLimiter, steamIds: string[]): Promise<Map<string, PlayerSummary>> {
165	  const out = new Map<string, PlayerSummary>();
166	  const unique = [...new Set(steamIds.filter(Boolean))];
167	  for (let i = 0; i < unique.length; i += 100) {
168	    const slice = unique.slice(i, i + 100);
169	    const url = `${API}/ISteamUser/GetPlayerSummaries/v2/?key=${STEAM_KEY}&steamids=${slice.join(",")}`;
170	    const res = await apiFetch(limiter, url);
171	    if (!res.ok) continue;
172	    const body = (await res.json()) as { response?: { players?: PlayerSummary[] } };
173	    for (const p of body.response?.players ?? []) out.set(p.steamid, p);
174	  }
175	  return out;
176	}
