178	async function importFamily(opts: {
179	  family: string;
180	  appid: number;
181	  limiter: RateLimiter;
182	  apply: boolean;
183	  minSubscriptions: number;
184	  maxPerFamily: number;
185	  maxPages?: number;
186	}): Promise<Counters> {
187	  const { family, appid, limiter, apply, minSubscriptions, maxPerFamily, maxPages } = opts;
188	  const counters = emptyCounters();
189	  let cursor = "*";
190	  let page = 0;
191	  let total: number | undefined;
192	  const qualifiedBatch: PublishedFile[] = [];
193	
194	  for (;;) {
195	    if (maxPages !== undefined && page >= maxPages) break;
196	    if (counters.qualified >= maxPerFamily) break;
197	
198	    const url =
199	      `${API}/IPublishedFileService/QueryFiles/v1/` +
200	      `?key=${STEAM_KEY}&appid=${appid}&numperpage=${PAGE_SIZE}&cursor=${encodeURIComponent(cursor)}` +
201	      `&query_type=${RANKED_BY_TOTAL_UNIQUE_SUBSCRIPTIONS}&return_short_description=true&format=json`;
202	    const res = await apiFetch(limiter, url);
203	    page++;
204	    if (!res.ok) {
205	      console.error(`  [${family}] HTTP ${res.status} at page ${page} — stopping this family early`);
206	      break;
207	    }
208	    const body = (await res.json()) as QueryFilesResponse & { response: { next_cursor?: string } };
209	    const items = body.response.publishedfiledetails ?? [];
210	    total = body.response.total ?? total;
211	    counters.seen += items.length;
212	    if (items.length === 0) break;
213	
214	    let sawBelowFloor = false;
215	    for (const item of items) {
216	      if (item.result !== 1 || item.banned || (item.visibility ?? 0) !== 0) continue;
217	      const subs = item.subscriptions ?? 0;
218	      if (subs < minSubscriptions) {
219	        sawBelowFloor = true;
220	        break; // sorted descending by subscriptions — nothing after this qualifies either
221	      }
222	      if (!item.title || !item.publishedfileid) continue;
223	      qualifiedBatch.push(item);
224	      counters.qualified++;
225	      if (counters.qualified >= maxPerFamily) break;
226	    }
227	
228	    const nextCursor = (body.response as { next_cursor?: string }).next_cursor;
229	    console.log(
230	      `  [${family}] page=${page} fetched=${items.length} qualified_running=${counters.qualified} total=${total ?? "?"}`
231	    );
232	    if (sawBelowFloor || !nextCursor || nextCursor === cursor) break;
233	    cursor = nextCursor;
234	  }
235	
236	  if (qualifiedBatch.length === 0) {
237	    console.log(`  [${family}] nothing qualified (floor=${minSubscriptions} subscribers)`);
238	    return counters;
239	  }
240	
241	  if (!apply) {
242	    counters.upserted = qualifiedBatch.length;
243	    return counters;
244	  }
245	
246	  const authors = await fetchAuthors(limiter, qualifiedBatch.map((i) => i.creator ?? ""));
247	  const CONCURRENCY = 8;
248	  for (let i = 0; i < qualifiedBatch.length; i += CONCURRENCY) {
249	    const slice = qualifiedBatch.slice(i, i + CONCURRENCY);
250	    await Promise.all(
251	      slice.map(async (item) => {
252	        const publishedFileId = item.publishedfileid;
253	        const slug = `${kebab(item.title!)}-${publishedFileId.slice(-6)}`;
254	        const author = item.creator ? authors.get(item.creator) : undefined;
255	        const data = {
256	          name: item.title!,
257	          category: "Workshop",
258	          description: item.short_description || null,
259	          iconUrl: item.preview_url || null,
260	          url: `https://steamcommunity.com/sharedfiles/filedetails/?id=${publishedFileId}`,
261	          downloads: item.subscriptions ?? null,
262	          license: null,
263	          serverSide: null,
264	          galleryUrls: [] as string[],
265	          authorName: author?.personaname ?? null,
266	          authorAvatarUrl: author?.avatarfull ?? null,
267	          source: "steam_workshop",
268	          sourceId: publishedFileId,
269	          active: true,
270	          verifiedAt: new Date(),
271	          upstreamOk: true,
272	          upstreamNote: null,
273	        };
274	        try {
275	          const existing = await db.gameMod.findUnique({
276	            where: { gameFamily_slug: { gameFamily: family, slug } },
277	            select: { id: true },
278	          });
279	          // select: { id: true } — a concurrent agent worktree sharing this
280	          // tree's node_modules regenerated the Prisma client against a schema
281	          // ahead of this database (a real `longDescription` column drift,
282	          // unrelated to this script); limiting the returned shape avoids
283	          // asking Postgres for a column this database doesn't have yet
284	          // rather than papering over it by touching the shared client.
285	          await db.gameMod.upsert({
286	            where: { gameFamily_slug: { gameFamily: family, slug } },
287	            update: data,
288	            create: { gameFamily: family, slug, ...data },
289	            select: { id: true },
290	          });
291	          counters.upserted++;
292	          if (existing) counters.updated++;
293	          else counters.created++;
294	        } catch (e) {
295	          counters.failed++;
296	          console.error(`  [db] ${family}/${slug} failed:`, e instanceof Error ? e.message : e);
297	        }
298	      })
299	    );
300	  }
301	  return counters;
302	}
303	
304	async function main() {
305	  const args = parseArgs(process.argv.slice(2));
306	  console.log(
307	    `[import-steamworkshop-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
308	      `families: ${args.families.join(", ")}; threshold: subscriptions>=${args.minSubscriptions}; ` +
309	      `max-per-family=${args.maxPerFamily}; rate=${args.ratePerMin}/min${args.maxPages ? `; max-pages=${args.maxPages} (smoke test)` : ""}`
310	  );
311	
312	  const limiter = new RateLimiter(args.ratePerMin);
313	  const totals = emptyCounters();
314	  const perFamily: Record<string, Counters> = {};
315	
316	  for (const family of args.families) {
317	    console.log(`\n=== ${family} (appid ${FAMILY_APPID[family]}) ===`);
318	    const counters = await importFamily({
319	      family,
320	      appid: FAMILY_APPID[family],
321	      limiter,
322	      apply: args.apply,
323	      minSubscriptions: args.minSubscriptions,
324	      maxPerFamily: args.maxPerFamily,
325	      maxPages: args.maxPages,
326	    });
327	    perFamily[family] = counters;
328	    for (const k of Object.keys(totals) as (keyof Counters)[]) totals[k] += counters[k];
329	    console.log(
330	      `--- ${family} done: seen=${counters.seen} qualified=${counters.qualified} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} failed=${counters.failed} ---`
331	    );
332	  }
333	
334	  console.log(`\n============================================================`);
335	  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
336	  for (const family of args.families) {
337	    const c = perFamily[family]!;
338	    console.log(
339	      `  ${family.padEnd(15)} seen=${c.seen.toString().padStart(6)} qualified=${c.qualified.toString().padStart(5)} upserted=${c.upserted.toString().padStart(5)} created=${c.created.toString().padStart(5)} updated=${c.updated.toString().padStart(5)} failed=${c.failed}`
340	    );
341	  }
342	  console.log(
343	    `  ${"TOTAL".padEnd(15)} seen=${totals.seen.toString().padStart(6)} qualified=${totals.qualified.toString().padStart(5)} upserted=${totals.upserted.toString().padStart(5)} created=${totals.created.toString().padStart(5)} updated=${totals.updated.toString().padStart(5)} failed=${totals.failed}`
344	  );
345	}
346	
347	main()
348	  .then(() => process.exit(0))
349	  .catch((e) => {
350	    console.error(e);
351	    process.exit(1);
352	  });
