1	/**
2	 * Bulk-import the real Thunderstore catalogue into `GameMod` for NxLabs Phase 3
3	 * — the Thunderstore counterpart to `scripts/import-modrinth-catalog.ts`, same
4	 * shape, same safety rails, same idempotency guarantee. Read that script's
5	 * header first if you haven't; this one only documents where Thunderstore's
6	 * real API and legal situation force a different approach.
7	 *
8	 * GAMES COVERED (priority order, see COMMUNITY_TO_FAMILY below for the exact
9	 * Thunderstore-community → this-repo's-GameFamily mapping, checked live
10	 * against lib/games.ts's GAME_FAMILIES and lib/game-control.ts's GAME_CONTROL):
11	 *   1. valheim              (gameFamily "valheim")
12	 *   2. sons-of-the-forest   (gameFamily "sonsoftheforest")
13	 *   3. schedule-i           (gameFamily "schedule1")
14	 *   4. sunkenland           (gameFamily "sunkenland")
15	 *
16	 * SOURCE: Thunderstore's public v1 catalogue API,
17	 * `https://thunderstore.io/c/{community}/api/v1/package/` — fully open, no
18	 * auth, no documented rate limit. Unlike Modrinth this is NOT a paged search
19	 * endpoint: one GET returns the community's ENTIRE package list as a single
20	 * JSON array (confirmed live 2026-09-20: valheim alone is ~11.5k packages /
21	 * ~168MB of JSON, because every package embeds its full version history).
22	 * So this script makes exactly one HTTP request per community — no rate
23	 * limiter, no pagination loop, no offset bookkeeping needed at all.
24	 *
25	 * ---------------------------------------------------------------------------
26	 * LEGAL / FETCH-AT-INSTALL-ONLY (do not deviate — established this session)
27	 * ---------------------------------------------------------------------------
28	 * Thunderstore publishes NO license field anywhere in the API or manifest
29	 * spec, and has NO published Terms of Service at all (verified 5 independent
30	 * ways earlier this session). Default copyright applies to every package.
31	 * Consequences, both already true of the existing 21 Phase-1 rows and kept
32	 * true here:
33	 *   - `license` is always written as `null`. Never fabricate one.
34	 *   - This script NEVER downloads/mirrors/rehosts an actual mod .zip. It
35	 *     stores metadata + the hotlinked Thunderstore CDN icon URL only. The
36	 *     real file is fetched at INSTALL TIME, by the worker
37	 *     (worker/game-mods.ts's `resolveUrl()` → the experimental per-package
38	 *     endpoint → a direct curl on the customer's own VM), exactly like today.
39	 *     This script performs zero downloads of mod content, only the catalogue
40	 *     JSON itself.
41	 *
42	 * ---------------------------------------------------------------------------
43	 * FIELD SEMANTICS MUST MATCH `scripts/verify-gamemods.ts`'s `verifyThunderstore()`
44	 * ---------------------------------------------------------------------------
45	 * That function is the periodic freshness pass for every thunderstore row
46	 * (this repo's real, already-shipped precedent for what "the truth" looks
47	 * like for this source) and it unconditionally OVERWRITES license,
48	 * gameVersions, loaders, fileBytes, serverSide, and galleryUrls back to
49	 * null/[] every time it runs, because Thunderstore's experimental per-package
50	 * endpoint (which it calls) doesn't expose richer versions of any of them.
51	 * The v1 catalogue endpoint THIS script calls happens to carry a bit more
52	 * (e.g. per-version `file_size`) — but writing that in now only for the next
53	 * verify-gamemods.ts run to erase it back to null would make the catalogue's
54	 * numbers visibly flap on every cron cycle for no benefit. So, deliberately,
55	 * this script writes the exact same null/[] values verifyThunderstore() does:
56	 *   license: null · gameVersions: [] · loaders: [] · fileBytes: null ·
57	 *   serverSide: null · galleryUrls: []
58	 * `downloads` and `dependencyCount` are matched to the SAME definition
59	 * verifyThunderstore() uses too — the LATEST version's own numbers
60	 * (`pkg.latest.downloads` / `pkg.latest.dependencies.length`), NOT a sum
61	 * across a package's whole version history — so a value this script writes
62	 * and a value the next verify pass writes never disagree over what
63	 * "downloads" even means for the same package.
64	 * `authorName` is the package's real owner/namespace (Thunderstore has no
65	 * separate "original author" field anywhere in its API distinct from the
66	 * uploading team — checked live; verifyThunderstore() makes the same call).
67	 * `authorAvatarUrl` stays null (no per-user avatar exists in this API).
68	 *
69	 * ---------------------------------------------------------------------------
70	 * QUALITY GATE (documented, not guessed)
71	 * ---------------------------------------------------------------------------
72	 * Applied to ALL four communities:
73	 *   - Skip `is_deprecated` packages. Real, and large: 5,282 of valheim's
74	 *     11,522 packages (45.8%) are deprecated — importing them as live
75	 *     catalogue content would be actively wrong, not just noisy.
76	 *   - Skip `has_nsfw_content` packages. Small (79/11522 valheim, 1/81 SOTF,
77	 *     5/523 schedule-i, 0/45 sunkenland) but a real, free, API-native signal
78	 *     a customer-facing hosting storefront should act on.
79	 *   - Skip packages tagged `Client-side` in `categories` UNLESS also tagged
80	 *     `Server-side`. This is Thunderstore's loose analogue of Modrinth's
81	 *     `environment` facet, and this repo's own GameMod.serverSide doc comment
82	 *     already states the principle: "a client-only mod cannot be installed
83	 *     on a server at all, and the catalogue should not offer it." Only
84	 *     valheim actually uses this tag pair in practice (checked live across
85	 *     all 4 communities); it removes 680 client-only packages there. A
86	 *     package with NEITHER tag is kept (ambiguous, not evidence of
87	 *     client-only — same reasoning Modrinth's own "plugin + unknown" carve-out
88	 *     used for an analogous gap).
89	 * Applied to valheim ONLY (min-downloads floor):
90	 *   - Latest-version downloads > 1,000 (DEFAULT_MIN_DOWNLOADS_VALHEIM,
91	 *     override with --min-downloads). Needed because valheim alone is
92	 *     11.5k packages deep — the other three communities (81 / 523 / 45 raw
93	 *     packages) are already small enough that a floor would just discard
94	 *     real, legitimate niche content without solving any actual scale
95	 *     problem (sunkenland's OWN 45-package total makes this obvious: there
96	 *     is no "top slice" to cut, you import what's there). Checked live: of
97	 *     valheim's 5,033 packages that clear the deprecated+client-only gates,
98	 *     1,235 clear latest-version-downloads>1000 too — a real ~25% cut,
99	 *     comparable in spirit (not identical numbers) to how selective
100	 *     Modrinth's own downloads>1000-OR-follows>50 gate is over its full
101	 *     catalogue.
102	 *   - Modrinth's script also runs a second, disjoint pass on `follows` to
103	 *     catch newer-but-well-liked projects the downloads floor alone would
104	 *     miss. Tried the Thunderstore equivalent (`rating_score`, the closest
105	 *     thing Thunderstore has to "follows") before deciding against it:
106	 *     checked live how many valheim packages have rating_score>20 AND
107	 *     downloads<=1000 (i.e. what a disjoint second pass would actually add)
108	 *     — zero. On Thunderstore, rating and downloads correlate too tightly
109	 *     for a second pass to catch anything a single downloads floor doesn't
110	 *     already have. Documenting the finding here instead of carrying a
111	 *     provably-dead code path.
112	 *
113	 * ---------------------------------------------------------------------------
114	 * IDENTITY / SLUG STRATEGY (why this isn't a plain slugify-and-go)
115	 * ---------------------------------------------------------------------------
116	 * Real identity on Thunderstore is `full_name` (`{owner}-{name}`), globally
117	 * unique — that's what's stored in `sourceId`, and it's the same value
118	 * `worker/game-mods.ts`'s `resolveUrl()` already parses to hit the real
119	 * per-package API at install time. `slug` is a separate, repo-local, kebab
120	 * identifier that only has to be unique per gameFamily — but Phase 1 already
121	 * hand-picked human-friendly slugs for 21 valheim/thunderstore rows (e.g.
122	 * sourceId "denikson-BepInExPack_Valheim" → slug "bepinex-valheim") that a
123	 * mechanical kebab-case of `full_name` would NOT reproduce
124	 * ("denikson-bepinexpack-valheim"). Re-deriving slugs mechanically for
125	 * packages that already have a row would therefore silently create a SECOND
126	 * row for the same real package instead of upserting onto the first one —
127	 * exactly the duplication this script must not cause.
128	 * So: for every package, look up an existing row by (gameFamily, source:
129	 * "thunderstore", sourceId) FIRST. Found → reuse its existing slug verbatim
130	 * (never touch slug on update). Not found → mechanically slugify(full_name),
131	 * de-duplicated against every slug already used in that gameFamily (existing
132	 * rows + everything already assigned earlier in this same run), suffixing
133	 * -2/-3/... on collision. The actual write is still a plain
134	 * `db.gameMod.upsert` on the real `@@unique([gameFamily, slug])` constraint,
135	 * same as Modrinth's script — the sourceId lookup only decides WHICH slug to
136	 * upsert on. Re-running the script finds the same sourceId → same slug →
137	 * pure update, created=0, same idempotency contract as Modrinth's script.
138	 *
139	 * `popularity` and `featured` are deliberately left OUT of the write payload
140	 * entirely — on create they get Prisma's real defaults (0 / false), and on
141	 * update they are never touched, so Phase 1's genuine editorial calls (e.g.
142	 * BepInExPack/Jotunn hand-marked `featured: true`) survive this bulk pass
143	 * untouched. This matches import-modrinth-catalog.ts's own `data` object,
144	 * which never sets popularity/featured either.
145	 *
146	 * ---------------------------------------------------------------------------
147	 * KNOWN GAP, DOCUMENTED RATHER THAN SILENTLY LEFT (not this script's job to fix)
148	 * ---------------------------------------------------------------------------
149	 * `lib/mod-install-support.ts`'s INSTALLABLE_FAMILIES is {minecraft, rust,
150	 * valheim} — sonsoftheforest/schedule1/sunkenland are NOT in it yet, so
151	 * their imported rows will render with "install it yourself in Files"
152	 * rather than a one-click Install button (installSupport()'s documented,
153	 * intentional degrade — the same state ~178 of the Modrinth-side entries are
154	 * already in for families the worker can't reach, per that module's own
155	 * comment). `RESOLVABLE_SOURCES` already includes "thunderstore" and
156	 * `resolveUrl()`'s thunderstore case is source-keyed, not family-keyed, so it
157	 * already works correctly for these three families' packages the moment
158	 * their family gains a `modDirShell` case — that's real, separate follow-up
159	 * work (adding directory-discovery shell snippets for three more games),
160	 * not a blocker for importing the catalogue data itself.
161	 *
162	 * SAFETY: same as every other writing script in this repo — dry run by
163	 * default, `scripts/db-target-guard.ts` enforces NXEON_DB_TARGET.
164	 *
165	 *   Dry run, one small community first:
166	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-thunderstore-catalog.ts \
167	 *       --communities=sunkenland
168	 *
169	 *   Real write, same slice:
170	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-thunderstore-catalog.ts \
171	 *       --communities=sunkenland --apply
172	 *
173	 *   Full real run (all 4 communities, default thresholds):
174	 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-thunderstore-catalog.ts --apply
175	 */
176	
177	import { assertDbTarget } from "./db-target-guard";
178	assertDbTarget("import-thunderstore-catalog.ts");
179	
180	import { db } from "../lib/db";
181	import type { GameFamily } from "../lib/games";
182	
183	const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
184	const DEFAULT_MIN_DOWNLOADS_VALHEIM = 1000;
185	const REQUEST_TIMEOUT_MS = 120_000;
186	
187	const ALL_COMMUNITIES = ["valheim", "sons-of-the-forest", "schedule-i", "sunkenland"] as const;
188	type Community = (typeof ALL_COMMUNITIES)[number];
189	
190	/** Checked live against lib/games.ts's GAME_FAMILIES and lib/game-control.ts's GAME_CONTROL — see file header. */
191	const COMMUNITY_TO_FAMILY: Record<Community, GameFamily> = {
192	  valheim: "valheim",
193	  "sons-of-the-forest": "sonsoftheforest",
194	  "schedule-i": "schedule1",
195	  sunkenland: "sunkenland",
196	};
197	
198	/** Communities that get a min-downloads floor, and what it is. Only valheim's
199	 *  catalogue is large enough to need one — see file header QUALITY GATE. */
200	const MIN_DOWNLOADS_FLOOR: Partial<Record<Community, number>> = {
201	  valheim: DEFAULT_MIN_DOWNLOADS_VALHEIM,
202	};
203	
204	/** Thunderstore package category tags → this repo's category vocabulary
205	 *  (Admin/Content/Building/QoL/Core/Tweaks/Modpacks — the same buckets
206	 *  Phase 1's 21 hand-picked rows already use). Thunderstore's own tags are
207	 *  noisy per-community free text (seasonal update names, loader variants,
208	 *  a near-universal "Mods"), unlike Modrinth's fixed project_type, so this
209	 *  is a best-effort priority match against the few tags that actually carry
210	 *  real category meaning; anything else — including the very common "Mods",
211	 *  "Misc", "Utility"-without-"Tools", seasonal update names, "AI Generated",
212	 *  language tags — falls through to the generic "Content" bucket, same as
213	 *  Modrinth's own default bucket for anything it can't classify further. */
214	const CATEGORY_RULES: Array<[string, string]> = [
215	  ["Modpacks", "Modpacks"],
216	  ["Libraries", "Core"],
217	  ["Tweaks", "Tweaks"],
218	  ["Building", "Building"],
219	  ["Tools", "Admin"],
220	];
221	function categoryFor(categories: string[]): string {
222	  for (const [raw, mapped] of CATEGORY_RULES) {
223	    if (categories.includes(raw)) return mapped;
224	  }
225	  return "Content";
226	}
227	
228	function slugify(fullName: string): string {
229	  const s = fullName
230	    .toLowerCase()
231	    .replace(/[^a-z0-9]+/g, "-")
232	    .replace(/^-+|-+$/g, "");
233	  return s.slice(0, 80) || "mod";
234	}
235	
236	// ── Thunderstore v1 catalogue types (only the fields we read) ───────────────
237	type PackageVersion = {
238	  icon?: string | null;
239	  description?: string | null;
240	  download_url?: string;
241	  downloads?: number;
242	  date_created?: string;
243	  dependencies?: unknown[];
244	};
245	type Package = {
246	  name: string;
247	  full_name: string;
248	  owner: string;
249	  package_url: string;
250	  categories?: string[];
251	  is_deprecated?: boolean;
252	  has_nsfw_content?: boolean;
253	  versions?: PackageVersion[];
254	};
255	
256	/** The version with the newest date_created — versions[] isn't documented as
257	 *  sorted, so this doesn't assume it (confirmed live it usually is newest-
258	 *  first, but "usually" isn't good enough for what we treat as ground truth). */
259	function latestVersion(pkg: Package): PackageVersion | null {
260	  const vs = pkg.versions ?? [];
261	  if (vs.length === 0) return null;
262	  return vs.reduce((a, b) => (new Date(b.date_created ?? 0) > new Date(a.date_created ?? 0) ? b : a));
263	}
264	
265	function isClientOnly(categories: string[]): boolean {
266	  return categories.includes("Client-side") && !categories.includes("Server-side");
267	}
268	
269	function displayNameFrom(rawName: string): string {
270	  return rawName.replace(/_/g, " ").trim() || rawName;
271	}
272	
273	// ── CLI args ──────────────────────────────────────────────────────────────
274	function parseArgs(argv: string[]) {
275	  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
276	  const communitiesArg = get("communities");
277	  const communities = (communitiesArg ? communitiesArg.split(",") : [...ALL_COMMUNITIES]).filter(
278	    (c): c is Community => (ALL_COMMUNITIES as readonly string[]).includes(c)
279	  );
280	  return {
281	    apply: argv.includes("--apply"),
282	    minDownloadsValheim: Number(get("min-downloads") ?? DEFAULT_MIN_DOWNLOADS_VALHEIM),
283	    limit: get("limit") ? Number(get("limit")) : undefined, // smoke-test cap on ELIGIBLE packages processed per community
284	    communities: communities.length ? communities : [...ALL_COMMUNITIES],
285	  };
286	}
287	
288	type Counters = { raw: number; deprecated: number; nsfw: number; clientOnly: number; belowFloor: number; eligible: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
289	function emptyCounters(): Counters {
290	  return { raw: 0, deprecated: 0, nsfw: 0, clientOnly: 0, belowFloor: 0, eligible: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
291	}
292	
293	async function fetchCommunity(community: Community): Promise<Package[]> {
294	  const url = `https://thunderstore.io/c/${community}/api/v1/package/`;
295	  const controller = new AbortController();
296	  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
297	  try {
298	    const res = await fetch(url, { headers: { "User-Agent": UA }, signal: controller.signal });
299	    if (!res.ok) throw new Error(`Thunderstore API returned HTTP ${res.status} for ${community}`);
300	    return (await res.json()) as Package[];
301	  } finally {
302	    clearTimeout(timer);
303	  }
304	}
305	
306	async function importCommunity(opts: { community: Community; apply: boolean; minDownloadsFloor: number; limit?: number }) {
307	  const { community, apply, minDownloadsFloor, limit } = opts;
308	  const gameFamily = COMMUNITY_TO_FAMILY[community];
309	  const counters = emptyCounters();
310	
311	  console.log(`\n=== ${community} → gameFamily "${gameFamily}" ===`);
312	  console.log(`  fetching full catalogue (single request, no pagination)...`);
313	  const all = await fetchCommunity(community);
314	  counters.raw = all.length;
315	  console.log(`  fetched ${all.length} raw packages`);
316	
317	  // Preload every existing thunderstore row for this family — this is what
318	  // makes the slug strategy (see file header) work without a per-package
319	  // DB round trip: sourceId → existing slug, plus every slug already in use.
320	  const existingRows = await db.gameMod.findMany({
321	    where: { gameFamily, source: "thunderstore" },
322	    select: { slug: true, sourceId: true },
323	  });
324	  const slugBySourceId = new Map<string, string>();
325	  const usedSlugs = new Set<string>();
326	  for (const row of existingRows) {
327	    usedSlugs.add(row.slug);
328	    if (row.sourceId) slugBySourceId.set(row.sourceId, row.slug);
329	  }
330	  console.log(`  ${existingRows.length} existing thunderstore row(s) already in this family`);
331	
332	  const eligible: Array<{ pkg: Package; latest: PackageVersion }> = [];
333	  for (const pkg of all) {
334	    if (pkg.is_deprecated) {
335	      counters.deprecated++;
336	      continue;
337	    }
338	    if (pkg.has_nsfw_content) {
339	      counters.nsfw++;
340	      continue;
341	    }
342	    const categories = pkg.categories ?? [];
343	    if (isClientOnly(categories)) {
344	      counters.clientOnly++;
345	      continue;
346	    }
347	    const latest = latestVersion(pkg);
348	    if (!latest) {
349	      counters.skipped++;
350	      continue;
351	    }
352	    const downloads = typeof latest.downloads === "number" ? latest.downloads : 0;
353	    if (downloads <= minDownloadsFloor) {
354	      counters.belowFloor++;
355	      continue;
356	    }
357	    eligible.push({ pkg, latest });
358	  }
359	  counters.eligible = eligible.length;
360	  const toProcess = limit ? eligible.slice(0, limit) : eligible;
361	  console.log(
362	    `  gate: raw=${counters.raw} deprecated=${counters.deprecated} nsfw=${counters.nsfw} client-only=${counters.clientOnly} ` +
363	      `below-floor(>${minDownloadsFloor})=${counters.belowFloor} eligible=${counters.eligible}` +
364	      (limit ? ` (processing first ${toProcess.length} per --limit)` : "")
365	  );
366	
367	  const CONCURRENCY = 8;
368	  for (let i = 0; i < toProcess.length; i += CONCURRENCY) {
369	    const slice = toProcess.slice(i, i + CONCURRENCY);
370	    await Promise.all(
371	      slice.map(async ({ pkg, latest }) => {
372	        if (!pkg.full_name || !pkg.owner) {
373	          counters.skipped++;
374	          return;
375	        }
376	        // Resolve slug: reuse an existing row's slug (Phase 1's hand-picked
377	        // ones included) if this exact package already has one; otherwise
378	        // mint a fresh, collision-checked one. See file header.
379	        let slug = slugBySourceId.get(pkg.full_name);
380	        const isNewRow = !slug;
381	        if (!slug) {
382	          const base = slugify(pkg.full_name);
383	          slug = base;
384	          let n = 2;
385	          while (usedSlugs.has(slug)) {
386	            slug = `${base}-${n}`;
387	            n++;
388	          }
389	          usedSlugs.add(slug);
390	          slugBySourceId.set(pkg.full_name, slug);
391	        }
392	
393	        const data = {
394	          name: displayNameFrom(pkg.name),
395	          category: categoryFor(pkg.categories ?? []),
396	          description: latest.description || null,
397	          iconUrl: latest.icon ?? null,
398	          url: pkg.package_url,
399	          downloads: typeof latest.downloads === "number" ? latest.downloads : null,
400	          // See file header "FIELD SEMANTICS MUST MATCH verifyThunderstore()":
401	          license: null,
402	          gameVersions: [] as string[],
403	          loaders: [] as string[],
404	          serverSide: null,
405	          galleryUrls: [] as string[],
406	          fileBytes: null,
407	          dependencyCount: latest.dependencies?.length ?? 0,
408	          authorName: pkg.owner,
409	          authorAvatarUrl: null,
410	          source: "thunderstore",
411	          sourceId: pkg.full_name,
412	          active: true,
413	          verifiedAt: new Date(),
414	          upstreamOk: true,
415	          upstreamNote: null,
416	        };
417	
418	        if (!apply) {
419	          counters.upserted++;
420	          if (isNewRow) counters.created++;
421	          else counters.updated++;
422	          return;
423	        }
424	        try {
425	          await db.gameMod.upsert({
426	            where: { gameFamily_slug: { gameFamily, slug: slug! } },
427	            update: data,
428	            create: { gameFamily, slug: slug!, ...data },
429	          });
430	          counters.upserted++;
431	          if (isNewRow) counters.created++;
432	          else counters.updated++;
433	        } catch (e) {
434	          counters.failed++;
435	          const msg = e instanceof Error ? e.message : String(e);
436	          console.error(`  [db] failed to upsert ${gameFamily}/${slug}: ${msg}`);
437	        }
438	      })
439	    );
440	  }
441	
442	  console.log(
443	    `--- ${community} done: upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} ` +
444	      `skipped=${counters.skipped} failed=${counters.failed} ---`
445	  );
446	  return counters;
447	}
