1	/**
2	 * Verify every seeded GameMod row against its real upstream source and write
3	 * back the facts the catalogue/install UI needs: iconUrl, downloads, license,
4	 * gameVersions, loaders, fileBytes, dependencyCount, serverSide, impact,
5	 * impactNote, verifiedAt, upstreamOk (+ upstreamNote).
6	 *
7	 * WHY THIS EXISTS. Every one of those fields has sat null/zero/true (the
8	 * default) on all 124 seeded rows since the catalogue was seeded — nothing in
9	 * this repo ever populated them. `lib/actions-mods.ts` and
10	 * `components/customer/gamepanel/v2/ModsPanel.tsx` both already read them and
11	 * both already say, in their own comments, that this script is what fills
12	 * them in. It also doubles as the "mark as no longer supported" mechanism the
13	 * owner asked for: re-running this periodically flips `upstreamOk` to false
14	 * (with a human-readable `upstreamNote`) the moment a project disappears
15	 * upstream, and the catalogue (getServerMods, and the public NxLabs pages)
16	 * already filter on `upstreamOk`.
17	 *
18	 * SOURCES COVERED THIS PASS: modrinth, spigotmc (via the public Spiget API),
19	 * thunderstore — the same three `worker/game-mods.ts` already knows how to
20	 * install from (RESOLVABLE_SOURCES in lib/mod-install-support.ts), so "we can
21	 * verify it" and "we can install it" track the same source list on purpose.
22	 * umod / github / nexus / codefling are deliberately left alone here — none of
23	 * them has a lightweight, well-documented "give me this exact project's
24	 * metadata by id" endpoint the way the three above do (umod.org has no public
25	 * read API at all; GitHub/Nexus would need per-repo/per-file heuristics with
26	 * real risk of wrong data). Their rows simply keep verifiedAt: null, which the
27	 * UI already renders as "unverified" rather than a fabricated tick — see
28	 * ModsPanel.tsx's comment on exactly this. Wiring those up is real, separate
29	 * follow-up work, not a blocker for shipping the majority (58 of 124 rows).
30	 *
31	 * IDEMPOTENT + RE-RUNNABLE: safe to run on a cron. Every write is a fresh
32	 * fetch-and-overwrite of the verified fields for that one row; nothing here
33	 * depends on the previous state except to compare for the summary counts.
34	 *
35	 * Run:  cd /opt/nxeon && npx tsx scripts/verify-gamemods.ts [--source=modrinth] [--limit=20]
36	 */
37	import { db } from "../lib/db";
38	
39	const UA = "Nxeon/1.0 (mod-verify; +https://nxeon.cloud)";
40	const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";
41	
42	type VerifyResult =
43	  | {
44	      ok: true;
45	      iconUrl: string | null;
46	      downloads: number | null;
47	      license: string | null;
48	      gameVersions: string[];
49	      loaders: string[];
50	      fileBytes: number | null;
51	      dependencyCount: number;
52	      serverSide: string | null;
53	      /** Real gallery/screenshot URLs from the source. Empty when it has none. */
54	      galleryUrls: string[];
55	      /** Real creator/team name + avatar, when the source resolves one. */
56	      authorName: string | null;
57	      authorAvatarUrl: string | null;
58	    }
59	  | { ok: false; note: string };
60	
61	/** light | moderate | heavy from real file size, plus a customer-facing note for the heavier tiers. */
62	function impactFromBytes(bytes: number | null): { impact: string; impactNote: string | null } {
63	  if (!bytes || bytes <= 0) return { impact: "light", impactNote: null };
64	  const mb = bytes / (1024 * 1024);
65	  if (mb >= 60) {
66	    return { impact: "heavy", impactNote: `Large download (~${Math.round(mb)} MB) — expect a slower install and a heavier footprint on your plan.` };
67	  }
68	  if (mb >= 12) {
69	    return { impact: "moderate", impactNote: `Medium-sized download (~${Math.round(mb)} MB).` };
70	  }
71	  return { impact: "light", impactNote: null };
72	}
