74	async function verifyModrinth(sourceId: string): Promise<VerifyResult> {
75	  const headers: Record<string, string> = { "User-Agent": UA };
76	  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;
77	
78	  const projRes = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}`, { headers });
79	  if (projRes.status === 404 || projRes.status === 410) {
80	    return { ok: false, note: "Removed from Modrinth (project no longer exists)." };
81	  }
82	  if (!projRes.ok) return { ok: false, note: `Modrinth API returned ${projRes.status}.` };
83	  const project = (await projRes.json()) as {
84	    icon_url?: string | null;
85	    downloads?: number;
86	    license?: { id?: string; name?: string };
87	    game_versions?: string[];
88	    loaders?: string[];
89	    server_side?: string;
90	    status?: string;
91	    team?: string;
92	    gallery?: Array<{ url: string; featured?: boolean; ordering?: number }>;
93	  };
94	  if (project.status && !["approved", "archived", "unlisted"].includes(project.status)) {
95	    return { ok: false, note: `Modrinth project status is "${project.status}".` };
96	  }
97	
98	  // Real gallery images — GET /v2/project/{id} already returned them above, no
99	  // extra call needed. Featured image first, then by the source's own
100	  // `ordering`, capped at 8 so a mod page never has to render dozens of thumbs.
101	  const galleryUrls = (project.gallery ?? [])
102	    .slice()
103	    .sort((a, b) => Number(b.featured) - Number(a.featured) || (a.ordering ?? 0) - (b.ordering ?? 0))
104	    .slice(0, 8)
105	    .map((g) => g.url);
106	
107	  // Real author/team — one extra call to the project's team endpoint. Best
108	  // effort: a team lookup failure loses only the author credit, never the
109	  // whole verification (the project-level facts above already succeeded).
110	  let authorName: string | null = null;
111	  let authorAvatarUrl: string | null = null;
112	  if (project.team) {
113	    try {
114	      const teamRes = await fetch(`https://api.modrinth.com/v2/team/${encodeURIComponent(project.team)}/members`, { headers });
115	      if (teamRes.ok) {
116	        const members = (await teamRes.json()) as Array<{
117	          role?: string;
118	          is_owner?: boolean;
119	          user?: { username?: string; avatar_url?: string | null };
120	        }>;
121	        const owner = members.find((m) => m.is_owner) ?? members[0];
122	        if (owner?.user?.username) {
123	          authorName = owner.user.username;
124	          authorAvatarUrl = owner.user.avatar_url ?? null;
125	        }
126	      }
127	    } catch {
128	      /* author credit is best-effort — see comment above */
129	    }
130	  }
131	
132	  let fileBytes: number | null = null;
133	  let dependencyCount = 0;
134	  try {
135	    const verRes = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}/version`, { headers });
136	    if (verRes.ok) {
137	      const versions = (await verRes.json()) as Array<{
138	        files: Array<{ url: string; primary: boolean; size?: number }>;
139	        dependencies?: unknown[];
140	      }>;
141	      const latest = versions[0];
142	      if (latest) {
143	        const f = latest.files.find((x) => x.primary) ?? latest.files[0];
144	        fileBytes = f?.size ?? null;
145	        dependencyCount = latest.dependencies?.length ?? 0;
146	      }
147	    }
148	  } catch {
149	    /* version lookup is best-effort — project-level facts above still apply */
150	  }
151	
152	  return {
153	    ok: true,
154	    iconUrl: project.icon_url ?? null,
155	    downloads: typeof project.downloads === "number" ? project.downloads : null,
156	    license: project.license?.id || project.license?.name || null,
157	    gameVersions: project.game_versions ?? [],
158	    loaders: project.loaders ?? [],
159	    fileBytes,
160	    dependencyCount,
161	    serverSide: project.server_side ?? null,
162	    galleryUrls,
163	    authorName,
164	    authorAvatarUrl,
165	  };
166	}
