168	async function verifySpigotmc(sourceId: string): Promise<VerifyResult> {
169	  const res = await fetch(`https://api.spiget.org/v2/resources/${encodeURIComponent(sourceId)}`, {
170	    headers: { "User-Agent": UA },
171	  });
172	  if (res.status === 404) return { ok: false, note: "Removed from SpigotMC (resource no longer exists)." };
173	  if (!res.ok) return { ok: false, note: `Spiget API returned ${res.status}.` };
174	  const resource = (await res.json()) as {
175	    downloads?: number;
176	    testedVersions?: string[];
177	    icon?: { url?: string };
178	    file?: { size?: number; sizeUnit?: string };
179	    author?: { id?: number };
180	  };
181	
182	  // Real author name — Spiget's resource payload only carries the author's
183	  // numeric id; one extra call resolves the display name. Best-effort, same
184	  // as Modrinth's team lookup above: a failure here loses only the credit.
185	  let authorName: string | null = null;
186	  if (resource.author?.id != null) {
187	    try {
188	      const authRes = await fetch(`https://api.spiget.org/v2/authors/${resource.author.id}`, { headers: { "User-Agent": UA } });
189	      if (authRes.ok) {
190	        const author = (await authRes.json()) as { name?: string };
191	        authorName = author.name ?? null;
192	      }
193	    } catch {
194	      /* best-effort */
195	    }
196	  }
197	  // Spiget's `existenceStatus` field is undocumented and was observed live
198	  // returning the integer 1 for unquestionably-live, well-known resources
199	  // (Vault, ProtocolLib, CMI — all with millions of real downloads) — it is
200	  // NOT a reliable "removed" signal, so it is not read here at all. A 404 on
201	  // this endpoint (handled above) is the only "gone" signal actually confirmed
202	  // against the real API.
203	  // Spiget's icon.url is relative to spigotmc.org; the file size is reported
204	  // in whatever unit sizeUnit says (almost always KB) — normalize to bytes.
205	  const iconUrl = resource.icon?.url ? `https://www.spigotmc.org/${resource.icon.url}` : null;
206	  const unit = (resource.file?.sizeUnit ?? "KB").toUpperCase();
207	  const rawSize = resource.file?.size ?? null;
208	  const fileBytes =
209	    rawSize == null ? null : unit === "MB" ? Math.round(rawSize * 1024 * 1024) : unit === "GB" ? Math.round(rawSize * 1024 * 1024 * 1024) : Math.round(rawSize * 1024);
210	
211	  return {
212	    ok: true,
213	    iconUrl,
214	    downloads: typeof resource.downloads === "number" ? resource.downloads : null,
215	    license: null, // Spiget doesn't publish a license field.
216	    gameVersions: resource.testedVersions ?? [],
217	    loaders: [],
218	    fileBytes,
219	    dependencyCount: 0,
220	    serverSide: null, // SpigotMC resources are always server plugins; no client/server split to report.
221	    galleryUrls: [], // Spiget doesn't expose a gallery endpoint.
222	    authorName,
223	    authorAvatarUrl: null, // Spiget's author record has no avatar field.
224	  };
225	}
