227	/** Thunderstore's package id in this catalogue is `<namespace>-<name>` (see worker/game-mods.ts's resolveUrl). */
228	async function verifyThunderstore(sourceId: string): Promise<VerifyResult> {
229	  const [namespace, ...rest] = sourceId.split("-");
230	  const name = rest.join("-");
231	  if (!namespace || !name) return { ok: false, note: `Unrecognized Thunderstore id "${sourceId}".` };
232	
233	  const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/`, {
234	    headers: { "User-Agent": UA },
235	  });
236	  if (res.status === 404) return { ok: false, note: "Removed from Thunderstore (package no longer exists)." };
237	  if (!res.ok) return { ok: false, note: `Thunderstore API returned ${res.status}.` };
238	  const pkg = (await res.json()) as {
239	    is_deprecated?: boolean;
240	    latest?: { icon?: string; downloads?: number; dependencies?: unknown[] };
241	  };
242	  if (pkg.is_deprecated) {
243	    return { ok: false, note: "Package is marked deprecated on Thunderstore." };
244	  }
245	  return {
246	    ok: true,
247	    iconUrl: pkg.latest?.icon ?? null,
248	    downloads: typeof pkg.latest?.downloads === "number" ? pkg.latest.downloads : null,
249	    license: null, // Thunderstore's package API doesn't publish a license field.
250	    // Thunderstore mod-loader packages aren't tagged to specific game versions
251	    // the way Modrinth projects are — real absence of data, not a bug.
252	    gameVersions: [],
253	    loaders: [],
254	    fileBytes: null, // not exposed by the experimental package endpoint
255	    dependencyCount: pkg.latest?.dependencies?.length ?? 0,
256	    serverSide: null,
257	    galleryUrls: [], // Thunderstore's package API doesn't expose a gallery.
258	    // The package namespace IS the real author identity on Thunderstore (a
259	    // real account/team name, not an invented one) — no separate avatar field.
260	    authorName: namespace,
261	    authorAvatarUrl: null,
262	  };
263	}
