271	async function main() {
272	  const args = process.argv.slice(2);
273	  const sourceArg = args.find((a) => a.startsWith("--source="))?.split("=")[1];
274	  const limitArg = args.find((a) => a.startsWith("--limit="))?.split("=")[1];
275	  const limit = limitArg ? Number(limitArg) : undefined;
276	
277	  const sources = sourceArg ? [sourceArg] : Object.keys(VERIFIERS);
278	  const unsupported = sourceArg && !VERIFIERS[sourceArg];
279	  if (unsupported) {
280	    console.error(`No verifier for source "${sourceArg}". Supported: ${Object.keys(VERIFIERS).join(", ")}`);
281	    process.exit(1);
282	  }
283	
284	  const mods = await db.gameMod.findMany({
285	    where: { source: { in: sources }, sourceId: { not: null } },
286	    orderBy: [{ gameFamily: "asc" }, { name: "asc" }],
287	    ...(limit ? { take: limit } : {}),
288	  });
289	
290	  console.log(`Verifying ${mods.length} mod(s) across source(s): ${sources.join(", ")}`);
291	
292	  let verified = 0;
293	  let failed = 0;
294	  let skipped = 0;
295	
296	  for (const mod of mods) {
297	    const verifier = VERIFIERS[mod.source];
298	    if (!verifier || !mod.sourceId) {
299	      skipped++;
300	      continue;
301	    }
302	    try {
303	      const result = await verifier(mod.sourceId);
304	      if (result.ok) {
305	        const { impact, impactNote } = impactFromBytes(result.fileBytes);
306	        await db.gameMod.update({
307	          where: { id: mod.id },
308	          data: {
309	            iconUrl: result.iconUrl,
310	            downloads: result.downloads,
311	            license: result.license,
312	            gameVersions: result.gameVersions,
313	            loaders: result.loaders,
314	            fileBytes: result.fileBytes,
315	            dependencyCount: result.dependencyCount,
316	            serverSide: result.serverSide,
317	            galleryUrls: result.galleryUrls,
318	            authorName: result.authorName,
319	            authorAvatarUrl: result.authorAvatarUrl,
320	            impact,
321	            impactNote,
322	            verifiedAt: new Date(),
323	            upstreamOk: true,
324	            upstreamNote: null,
325	          },
326	        });
327	        verified++;
328	        console.log(
329	          `  OK    ${mod.gameFamily}/${mod.slug} (${mod.source}) — downloads=${result.downloads ?? "?"} icon=${result.iconUrl ? "yes" : "no"} gallery=${result.galleryUrls.length} author=${result.authorName ?? "?"}`
330	        );
331	      } else {
332	        await db.gameMod.update({
333	          where: { id: mod.id },
334	          data: { upstreamOk: false, upstreamNote: result.note, verifiedAt: new Date() },
335	        });
336	        failed++;
337	        console.log(`  DEAD  ${mod.gameFamily}/${mod.slug} (${mod.source}) — ${result.note}`);
338	      }
339	    } catch (e) {
340	      failed++;
341	      const msg = e instanceof Error ? e.message : String(e);
342	      console.error(`  ERROR ${mod.gameFamily}/${mod.slug} (${mod.source}): ${msg}`);
343	    }
344	    // Be a polite API citizen — small delay between calls, no need to hammer
345	    // free public endpoints for a 124-row catalogue.
346	    await new Promise((r) => setTimeout(r, 150));
347	  }
348	
349	  const totalCatalog = await db.gameMod.count();
350	  const stillUnverified = await db.gameMod.count({ where: { verifiedAt: null } });
351	  console.log(
352	    `\nDone. verified=${verified} dead=${failed} skipped(no-verifier-or-id)=${skipped}. ` +
353	      `Catalog total=${totalCatalog}, still unverified (other sources)=${stillUnverified}.`
354	  );
355	}
