import { NextResponse } from "next/server";
import { getCatalogMod } from "@/lib/mods-catalog";

export async function GET(req: Request) {
  const url = new URL(req.url);
  const family = url.searchParams.get("family") ?? "minecraft";
  const slug = url.searchParams.get("slug") ?? "abyss+";
  try {
    const mod = await getCatalogMod(family, slug);
    return NextResponse.json({ family, slug, found: !!mod, mod: mod ? { name: mod.name, active: true } : null });
  } catch (e) {
    return NextResponse.json({ family, slug, error: e instanceof Error ? e.message : String(e), stack: e instanceof Error ? e.stack : undefined }, { status: 500 });
  }
}

