280	export function slugifyHeading(text: string): string {
281	  return (
282	    text
283	      .toLowerCase()
284	      .replace(/`[^`]*`/g, "")
285	      .replace(/[*_[\]()#]/g, "")
286	      .replace(/&[a-z]+;/g, "")
287	      .replace(/[^a-z0-9\s-]/g, "")
288	      .trim()
289	      .replace(/\s+/g, "-")
290	      .slice(0, 60)
291	      .replace(/^-+|-+$/g, "") || "section"
