/**
 * Renderer for third-party MOD BODY content — Modrinth project markdown,
 * Steam Workshop BBCode, Thunderstore READMEs. Deliberately separate from
 * lib/blog.ts's `renderMarkdown`, which stays first-party-only (blog posts,
 * admin docs, announcements, What's New) and keeps its simple
 * "escape everything, no raw HTML ever" model — that's correct for content
 * this repo's own authors write, but wrong here.
 *
 * WHY THIS EXISTS (2026-09-24 NxLabs description-gap fix): real Modrinth
 * project bodies routinely embed raw HTML inline with markdown — confirmed
 * live against the real API: `sodium`'s body contains literal `<center>`,
 * `<img>`; BepInExPack_Valheim's Thunderstore README contains `<details>`,
 * `<br>`. Piping that through lib/blog.ts's `esc()`-first renderer turns
 * every tag into visible literal text ("&lt;center&gt;This mod...&lt;/center&gt;")
 * instead of rendering it — exactly the bug this module fixes.
 *
 * SAFETY MODEL: every input is HTML-escaped FIRST (nothing here ever trusts
 * a raw `<` from an upstream source). A fixed ALLOW-LIST of simple tags is
 * then selectively restored by matching the ALREADY-ESCAPED text against
 * exact literal patterns (e.g. `&lt;center&gt;` -> `<center>`). An arbitrary
 * string from a mod body can never forge its way back into a real tag
 * unless it exactly matches one of the patterns below — attribute VALUES
 * (img src, a href) are extracted, validated (https-only, no javascript:/
 * data:), and re-emitted through a fresh, controlled template; the
 * attribute text itself is never echoed back verbatim. This is why this
 * approach is safe against injection despite rendering third-party-authored
 * HTML, without pulling in a new npm dependency (this repo's own convention
 * — see lib/blog.ts's own hand-rolled renderer, components/ui/charts.tsx's
 * dependency-free SVG charts).
 *
 * HEADING POLICY: every in-body heading (markdown `#`/`##`/`###`, BBCode
 * [h1]/[h2]/[h3]) is capped at `<h3>` — the page around this content already
 * has its own `<h1>` (the mod name) and `<h2>` ("Description"); a mod author
 * should never be able to inject a second, competing one.
 */

function esc(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function escAttr(s: string): string {
  return esc(s).replace(/"/g, "&quot;");
}

const CLS = {
  h3: "mt-6 mb-2 text-lg font-semibold text-white",
  p: "mb-4 leading-relaxed text-slate-300",
  ul: "mb-4 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  ol: "mb-4 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  li: "leading-relaxed",
  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
  img: "w-full rounded-xl border border-white/10 shadow-lg shadow-black/20 my-4",
  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
  pre: "mb-4 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
  blockquote: "mb-4 border-l-2 border-white/15 pl-4 italic text-slate-400",
  hr: "my-6 border-white/[0.08]",
};

/**
 * Only http(s) allowed, https FORCED (audit: "force https on embedded
 * images"). Protocol-relative `//host/img.png` gets an https: prefix.
 * Anything else (data:, javascript:, blob:, bare text) is rejected — the
 * caller drops the element entirely rather than render a broken/unsafe one.
 */
function safeImageSrc(u: string | null | undefined): string | null {
  if (!u) return null;
  const t = u.trim();
  if (/^https:\/\//i.test(t)) return t;
  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
  if (/^\/\//.test(t)) return `https:${t}`;
  return null;
}

/** Only http(s) or same-site root-relative allowed for links; else "#". */
function safeLinkHref(u: string | null | undefined): string {
  if (!u) return "#";
  const t = u.trim();
  if (/^https:\/\//i.test(t)) return t;
  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
  if (/^\//.test(t)) return t;
  return "#";
}

function extractAttr(attrs: string, name: string): string | null {
  const m = attrs.match(new RegExp(`${name}\\s*=\\s*"([^"]*)"`, "i")) ?? attrs.match(new RegExp(`${name}\\s*=\\s*'([^']*)'`, "i"));
  return m ? m[1] : null;
}

/** Simple wrap tags: no attributes ever kept, just the tag shell restored. */
const WRAP_TAG_MAP: Record<string, { open: string; close: string }> = {
  center: { open: '<div class="text-center">', close: "</div>" },
  details: { open: "<details>", close: "</details>" },
  summary: { open: '<summary class="cursor-pointer font-medium text-white">', close: "</summary>" },
  sub: { open: "<sub>", close: "</sub>" },
  sup: { open: "<sup>", close: "</sup>" },
  small: { open: '<span class="text-xs">', close: "</span>" },
  b: { open: "<strong class=\"font-semibold text-white\">", close: "</strong>" },
  strong: { open: "<strong class=\"font-semibold text-white\">", close: "</strong>" },
  i: { open: "<em>", close: "</em>" },
  em: { open: "<em>", close: "</em>" },
  u: { open: "<u>", close: "</u>" },
  s: { open: "<s>", close: "</s>" },
  strike: { open: "<s>", close: "</s>" },
  code: { open: `<code class="${CLS.code}">`, close: "</code>" },
  blockquote: { open: `<blockquote class="${CLS.blockquote}">`, close: "</blockquote>" },
};
const VOID_TAGS = new Set(["br", "hr"]);

/**
 * Restore a fixed allow-list of safe tags from ALREADY-ESCAPED text (see
 * file header for why this order is what makes it safe). Handles simple
 * wrap tags, void tags (br/hr), and the two attribute-carrying tags
 * (img/a) via strict extraction + revalidation, never verbatim echo.
 */
function restoreSafeHtml(escaped: string): string {
  let s = escaped;

  // Void tags: &lt;br&gt; / &lt;br/&gt; / &lt;br /&gt; / &lt;hr ...&gt;
  s = s.replace(/&lt;(br|hr)\s*\/?\s*&gt;/gi, (_m, tag: string) => `<${tag.toLowerCase()} />`);

  // img — attribute-carrying, strictly re-templated.
  s = s.replace(/&lt;img\s+([^&]*?)\/?\s*&gt;/gi, (_m, attrs: string) => {
    const src = safeImageSrc(extractAttr(attrs, "src"));
    if (!src) return "";
    const alt = extractAttr(attrs, "alt") ?? "";
    return `<img src="${escAttr(src)}" alt="${escAttr(alt)}" loading="lazy" class="${CLS.img}" />`;
  });

  // a — attribute-carrying, strictly re-templated. Opening + closing handled separately.
  s = s.replace(/&lt;a\s+([^&]*?)&gt;/gi, (_m, attrs: string) => {
    const href = safeLinkHref(extractAttr(attrs, "href"));
    const external = href.startsWith("http");
    return `<a class="${CLS.a}" href="${escAttr(href)}"${external ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>`;
  });
  s = s.replace(/&lt;\/a&gt;/gi, "</a>");

  // Simple wrap tags (open + close), no attributes ever kept.
  for (const [tag, { open, close }] of Object.entries(WRAP_TAG_MAP)) {
    s = s.replace(new RegExp(`&lt;${tag}(?:\\s[^&]*?)?&gt;`, "gi"), open);
    s = s.replace(new RegExp(`&lt;/${tag}\\s*&gt;`, "gi"), close);
  }

  return s;
}

// Private-use sentinels protecting inline code spans from further processing.
const S0 = "\uE000";
const S1 = "\uE001";

function inlineMd(text: string): string {
  const codes: string[] = [];
  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
    codes.push(c);
    return `${S0}${codes.length - 1}${S1}`;
  });
  s = restoreSafeHtml(s);
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
  s = s.replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, "<em>$1</em>");
  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_m, alt: string, u: string) => {
    const safe = safeImageSrc(u);
    if (!safe) return "";
    return `<img class="${CLS.img}" src="${safe}" alt="${escAttr(alt)}" loading="lazy" />`;
  });
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
    const safe = safeLinkHref(u);
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${t}</a>`;
  });
  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
  return s;
}

/**
 * Cut raw markdown SOURCE at a real paragraph/line boundary at or before
 * `maxChars`, never mid-word/mid-tag — replaces the old
 * `longDescription.slice(0, 6000)` raw character slice, which could (and,
 * on real bodies, did) cut in the middle of a markdown construct or a raw
 * HTML tag. Returns the untruncated text unchanged when it already fits.
 */
export function truncateMarkdown(md: string, maxChars = 6000): { text: string; truncated: boolean } {
  if (md.length <= maxChars) return { text: md, truncated: false };
  const window = md.slice(0, maxChars);
  const paraBreak = window.lastIndexOf("\n\n");
  const lineBreak = window.lastIndexOf("\n");
  const spaceBreak = window.lastIndexOf(" ");
  const cut = paraBreak > maxChars * 0.5 ? paraBreak : lineBreak > maxChars * 0.5 ? lineBreak : spaceBreak > 0 ? spaceBreak : maxChars;
  return { text: md.slice(0, cut).trimEnd(), truncated: true };
}

/** Real Markdown (Modrinth project body / Thunderstore README) -> sanitized HTML. */
export function renderModMarkdown(md: string): string {
  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }

    if (/^---+$/.test(line.trim())) { out.push(`<hr class="${CLS.hr}" />`); i++; continue; }

    // Fenced code block — contents escaped, never markdown/HTML processed.
    if (/^```/.test(line.trim())) {
      const buf: string[] = [];
      i++;
      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
      i++;
      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
      continue;
    }

    // Standalone image line -> figure.
    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
    if (img) {
      const safe = safeImageSrc(img[2]);
      if (safe) {
        out.push(`<img class="${CLS.img}" src="${safe}" alt="${escAttr(img[1])}" loading="lazy" />`);
        i++;
        continue;
      }
    }

    // Headings — ALL capped at h3 (see file header "HEADING POLICY").
    if (/^#{1,6}\s+/.test(line)) {
      out.push(`<h3 class="${CLS.h3}">${inlineMd(line.replace(/^#{1,6}\s+/, ""))}</h3>`);
      i++;
      continue;
    }

    // Ordered list.
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) { items.push(lines[i].replace(/^\s*\d+\.\s+/, "")); i++; }
      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inlineMd(t)}</li>`).join("")}</ol>`);
      continue;
    }

    // Unordered list.
    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) { items.push(lines[i].replace(/^\s*[-*]\s+/, "")); i++; }
      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inlineMd(t)}</li>`).join("")}</ul>`);
      continue;
    }

    // Paragraph — gather consecutive non-blank, non-block-start lines. This
    // is also what lets a real multi-line raw HTML block (e.g. Thunderstore
    // READMEs' `<details>\n<summary>...</summary>\ntext\n</details>`) join
    // into one text run that restoreSafeHtml() processes as a whole.
    const para = [line];
    i++;
    while (
      i < lines.length && lines[i].trim() &&
      !/^#{1,6}\s/.test(lines[i]) && !/^\s*[-*]\s+/.test(lines[i]) && !/^\s*\d+\.\s+/.test(lines[i]) &&
      !/^```/.test(lines[i].trim()) && !/^---+$/.test(lines[i].trim())
    ) { para.push(lines[i]); i++; }
    out.push(`<p class="${CLS.p}">${inlineMd(para.join(" "))}</p>`);
  }

  return out.join("\n");
}

/**
 * Steam Workshop's `file_description` — real BBCode, not markdown (verified
 * live: `[h1][b]I DID NOT CREATE THIS MAP![/b][/h1]`). Square brackets are
 * not HTML-meaningful, so `esc()` leaves BBCode tags untouched, letting the
 * same escape-first/allow-list-restore approach apply here too.
 */
export function renderBBCode(bbcode: string): string {
  const escaped = esc(bbcode ?? "");
  const lines = escaped.replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;

  const inlineBB = (text: string): string => {
    let s = text;
    s = s.replace(/\[b\]([\s\S]*?)\[\/b\]/gi, '<strong class="font-semibold text-white">$1</strong>');
    s = s.replace(/\[i\]([\s\S]*?)\[\/i\]/gi, "<em>$1</em>");
    s = s.replace(/\[u\]([\s\S]*?)\[\/u\]/gi, "<u>$1</u>");
    s = s.replace(/\[(?:strike|s)\]([\s\S]*?)\[\/(?:strike|s)\]/gi, "<s>$1</s>");
    s = s.replace(/\[url=([^\]]+)\]([\s\S]*?)\[\/url\]/gi, (_m, href: string, t: string) => {
      const safe = safeLinkHref(href);
      const ext = safe.startsWith("http");
      return `<a class="${CLS.a}" href="${escAttr(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${t}</a>`;
    });
    s = s.replace(/\[url\]([\s\S]*?)\[\/url\]/gi, (_m, href: string) => {
      const safe = safeLinkHref(href);
      const ext = safe.startsWith("http");
      return `<a class="${CLS.a}" href="${escAttr(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${href}</a>`;
    });
    s = s.replace(/\[img\]([\s\S]*?)\[\/img\]/gi, (_m, src: string) => {
      const safe = safeImageSrc(src.trim());
      return safe ? `<img class="${CLS.img}" src="${safe}" alt="" loading="lazy" />` : "";
    });
    return s;
  };

  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }

    // Headings — capped at h3, same policy as the markdown renderer.
    const h = line.trim().match(/^\[h[1-3]\]([\s\S]*?)\[\/h[1-3]\]\s*$/i);
    if (h) { out.push(`<h3 class="${CLS.h3}">${inlineBB(h[1])}</h3>`); i++; continue; }

    // [code]...[/code] — may span lines; contents left escaped, not BBCode-processed.
    if (/^\[code\]/i.test(line.trim())) {
      const buf: string[] = [line.replace(/^\[code\]/i, "")];
      i++;
      while (i < lines.length && !/\[\/code\]/i.test(lines[i])) { buf.push(lines[i]); i++; }
      if (i < lines.length) { buf.push(lines[i].replace(/\[\/code\].*$/i, "")); i++; }
      out.push(`<pre class="${CLS.pre}"><code>${buf.join("\n")}</code></pre>`);
      continue;
    }

    // [list]...[/list] with [*] items (Steam's BBCode list, no closing [/*]).
    if (/^\[list\]/i.test(line.trim())) {
      const items: string[] = [];
      i++;
      while (i < lines.length && !/^\[\/list\]/i.test(lines[i].trim())) {
        const t = lines[i].trim().replace(/^\[\*\]\s*/, "");
        if (t) items.push(t);
        i++;
      }
      if (i < lines.length) i++; // consume [/list]
      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inlineBB(t)}</li>`).join("")}</ul>`);
      continue;
    }

    if (/^\[quote/i.test(line.trim())) {
      const buf: string[] = [];
      const firstLineContent = line.replace(/^\[quote(?:=[^\]]*)?\]/i, "");
      if (firstLineContent.trim()) buf.push(firstLineContent);
      i++;
      while (i < lines.length && !/\[\/quote\]/i.test(lines[i])) { buf.push(lines[i]); i++; }
      if (i < lines.length) { const rest = lines[i].replace(/\[\/quote\].*$/i, ""); if (rest.trim()) buf.push(rest); i++; }
      out.push(`<blockquote class="${CLS.blockquote}">${inlineBB(buf.join(" "))}</blockquote>`);
      continue;
    }

    // Paragraph — gather until blank line.
    const para = [line];
    i++;
    while (i < lines.length && lines[i].trim() && !/^\[(?:h[1-3]|code|list|quote)/i.test(lines[i].trim())) { para.push(lines[i]); i++; }
    out.push(`<p class="${CLS.p}">${inlineBB(para.join(" "))}</p>`);
  }

  return out.join("\n");
}

export type ModBodySource = "modrinth" | "thunderstore" | "steam_workshop" | "other";

/**
 * Single entry point the two mod-detail pages call. Truncates the RAW
 * source at a real boundary first (never a mid-tag character slice), then
 * renders through the format-appropriate renderer.
 */
export function renderModBody(rawBody: string, source: ModBodySource, maxChars = 6000): { html: string; truncated: boolean } {
  const { text, truncated } = truncateMarkdown(rawBody, maxChars);
  const html = source === "steam_workshop" ? renderBBCode(text) : renderModMarkdown(text);
  return { html, truncated };
}

