/**
 * Best-effort `decodeURIComponent` — never throws. A slug containing a
 * literal `%` that isn't part of a real percent-escape (rare, but the
 * catalogue does have a handful of hand-typed source titles with one) would
 * make `decodeURIComponent` throw a `URIError`; callers here always want a
 * best-effort value back, not a 500.
 */
function safeDecode(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}

/**
 * One mod's detail. Returns null for an unknown/inactive slug — callers
 * should notFound().
 *
 * DECODES the slug/family before lookup (2026-09-24 fix — see
 * docs/DOCUMENTATION.md's dated entry): a page.tsx dynamic route segment
 * that also exports `generateStaticParams` gets its `params` value as the
 * STILL-PERCENT-ENCODED path segment in this Next.js version (confirmed
 * live: requesting `/mods/minecraft/abyss+` — or the equivalently-encoded
 * `/mods/minecraft/abyss%2B` — makes `params.slug` arrive as the literal
 * string `"abyss%2B"`, not `"abyss+"`; a plain Route Handler on the exact
 * same path shape decodes correctly, so this is specific to the
 * generateStaticParams + page.tsx combination). Real catalogue slugs
 * legitimately contain `+`, `,`, `` ` ``, `"` (Modrinth project slugs are
 * not sanitized at import) — 377 of them 404'd because of this. Tries the
 * decoded value first (the common, now-fixed case), then falls back to the
 * raw value passed in (covers the rare slug that is itself the literal
 * string containing a `%`, and keeps this function correct for callers that
 * already pass a clean, non-encoded value — decoding twice is a no-op for
 * any string with no percent-escapes in it).
 */
export async function getCatalogMod(family: string, slug: string): Promise<ModDetail | null> {
  const decodedFamily = safeDecode(family);
  const decodedSlug = safeDecode(slug);
  let row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: decodedFamily, slug: decodedSlug } } });
  if (!row && (decodedFamily !== family || decodedSlug !== slug)) {
    row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
  }
  if (!row || !row.active) return null;
  const aggs = await ratingAggs([row.id]);
  return toDetail(row, aggs.get(row.id));
}

