102	  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;
103	
104	  const projRes = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}`, { headers });
105	  if (projRes.status === 404 || projRes.status === 410) {
106	    return { ok: false, note: "Removed from Modrinth (project no longer exists)." };
107	  }
108	  if (!projRes.ok) return { ok: false, note: `Modrinth API returned ${projRes.status}.` };
109	  const project = (await projRes.json()) as {
110	    icon_url?: string | null;
111	    downloads?: number;
112	    license?: { id?: string; name?: string };
113	    game_versions?: string[];
114	    loaders?: string[];
115	    server_side?: string;
116	    status?: string;
117	    team?: string;
118	    gallery?: Array<{ url: string; featured?: boolean; ordering?: number }>;
119	  };
120	  if (project.status && !["approved", "archived", "unlisted"].includes(project.status)) {
