141	      if (teamRes.ok) {
142	        const members = (await teamRes.json()) as Array<{
143	          role?: string;
144	          is_owner?: boolean;
145	          user?: { username?: string; avatar_url?: string | null };
146	        }>;
147	        const owner = members.find((m) => m.is_owner) ?? members[0];
148	        if (owner?.user?.username) {
149	          authorName = owner.user.username;
150	          authorAvatarUrl = owner.user.avatar_url ?? null;
151	        }
152	      }
153	    } catch {
154	      /* author credit is best-effort — see comment above */
155	    }
156	  }
