class RateLimiter {
  private minIntervalMs: number;
  private last = 0;
  constructor(perMin: number) {
    this.minIntervalMs = 60_000 / perMin;
  }
  async wait() {
    const elapsed = Date.now() - this.last;
    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    this.last = Date.now();
  }
}

/**
 * Real longer body (2026-09-24 fix) — the v1 catalogue this script otherwise
 * runs on has NO body/description field beyond the short manifest
 * `description` (<=250 chars). The real README lives at the experimental
 * per-package, per-version endpoint (verified live: BepInExPack_Valheim's
 * README is 8,237 chars of real markdown) and needs one request per
 * package — there is no bulk form of this specific endpoint, unlike the v1
 * catalogue fetch above. Best-effort: any failure (404, timeout, malformed
 * JSON) returns null, same "leave the description short rather than guess"
 * rule as everything else in this file.
 */
async function fetchReadme(limiter: RateLimiter, namespace: string, name: string, versionNumber: string): Promise<string | null> {
  await limiter.wait();
  try {
    const url = `https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/${encodeURIComponent(versionNumber)}/readme/`;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 30_000);
    try {
      const res = await fetch(url, { headers: { "User-Agent": UA }, signal: controller.signal });
      if (!res.ok) return null;
      const body = (await res.json()) as { markdown?: string };
      return body.markdown?.trim() || null;
    } finally {
      clearTimeout(timer);
    }
  } catch {
    return null;
  }
}

