/** Crude BBCode-tag strip for deriving a plain-text short tagline — not a
 *  renderer (lib/mod-markdown.ts's renderBBCode is the real one, used at
 *  display time on the full `longDescription`), just enough to turn
 *  "[h1][b]Real Title[/b][/h1]" into "Real Title" for the `description`
 *  field/meta tags/card previews. */
function stripBBCodeToPlainText(s: string): string {
  return s
    .replace(/\[\/?[a-z0-9=*"'\s:./-]*?\]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Short tagline from the real file_description — word-boundary truncated,
 *  matching app/(marketing)/mods/[family]/[slug]/page.tsx's own
 *  metaDescriptionFor truncation convention (~157 chars + ellipsis). */
function shortDescriptionFrom(fileDescription: string | undefined, maxChars = 200): string | null {
  const plain = stripBBCodeToPlainText(fileDescription ?? "");
  if (!plain) return null;
  if (plain.length <= maxChars) return plain;
  const cut = plain.slice(0, maxChars);
  const lastSpace = cut.lastIndexOf(" ");
  return `${cut.slice(0, lastSpace > 100 ? lastSpace : maxChars)}…`;
}

