        description: item.description || null,
        iconUrl: item.icon_url || null,
        url: item.url || `https://umod.org/plugins/${item.slug}`,
        downloads: typeof item.downloads === "number" ? item.downloads : null,
        license: null,
        serverSide: null,
        authorName: item.author || null,
        authorAvatarUrl: null,
        source: SOURCE,
        sourceId: item.slug,
        active: true,
        verifiedAt: new Date(),
        upstreamOk: true,
        upstreamNote: null,
