// NOTE: `text` here is already-escaped (this whole function starts from
// `escaped = esc(bbcode)` above) — every URL embed below uses
// escAttrPostEscaped, not escAttr, for the same double-encoding reason
// documented on that helper. Found in review (2026-09-24): the `[img]`
// handler had no attribute-escaping at all (real injection via a crafted
// `[img]https://x.png" onerror=...[/img]`), and `[url=]`/`[url]` had the
// double-encoding correctness bug (not a security bug — over-escaping — but
// still wrong for a real query-string URL like `?id=1&mode=2`).
const inlineBB = (text: string): string => {
  let s = text;
  s = s.replace(/\[b\]([\s\S]*?)\[\/b\]/gi, '<strong class="font-semibold text-white">$1</strong>');
  s = s.replace(/\[i\]([\s\S]*?)\[\/i\]/gi, "<em>$1</em>");
  s = s.replace(/\[u\]([\s\S]*?)\[\/u\]/gi, "<u>$1</u>");
  s = s.replace(/\[(?:strike|s)\]([\s\S]*?)\[\/(?:strike|s)\]/gi, "<s>$1</s>");
  s = s.replace(/\[url=([^\]]+)\]([\s\S]*?)\[\/url\]/gi, (_m, href: string, t: string) => {
    const safe = safeLinkHref(href);
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${escAttrPostEscaped(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${t}</a>`;
  });
  s = s.replace(/\[url\]([\s\S]*?)\[\/url\]/gi, (_m, href: string) => {
    const safe = safeLinkHref(href);
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${escAttrPostEscaped(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${href}</a>`;
  });
  s = s.replace(/\[img\]([\s\S]*?)\[\/img\]/gi, (_m, src: string) => {
    const safe = safeImageSrc(src.trim());
    return safe ? `<img class="${CLS.img}" src="${escAttrPostEscaped(safe)}" alt="" loading="lazy" />` : "";
  });
  return s;

