import { renderModBody, renderModMarkdown, renderBBCode } from "../lib/mod-markdown";

function check(label: string, html: string) {
  const hasRawInjectedTag = /data-poc/i.test(html) && !/&amp;quot;|&quot;/.test(html.match(/data-poc[^"]*/)?.[0] ?? "data-poc"); // crude
  const brokeOutOfAttr = /"\s*>\s*<b[^&]*data-poc/i.test(html) || /"><b/i.test(html);
  console.log(`\n=== ${label} ===`);
  console.log(html);
  console.log(brokeOutOfAttr ? "!!! VULNERABLE — attribute break-out detected !!!" : "ok — no raw break-out found");
}

// Reviewer's exact repro strings
check("md image break-out", renderModMarkdown(`![a](https://x.png"><b data-poc="1">INJECTED</b>)`));
check("md inline image break-out", renderModMarkdown(`text ![a](https://x.png" data-poc="1) more`));
check("md inline link break-out", renderModMarkdown(`see [here](https://x.com" data-poc="1) ok`));
check("bbcode img break-out", renderBBCode(`[img]https://x.png" data-poc="1[/img]`));
check("bbcode url break-out", renderBBCode(`[url=https://x.com" data-poc="1]click[/url]`));

// Legit query-string URL should NOT be mangled/double-encoded
const legit = renderModMarkdown(`![logo](https://cdn.example.com/img.png?w=200&h=100 "title")`);
console.log("\n=== legit query-string URL (should show single &amp;, not &amp;amp;) ===");
console.log(legit);

const legitBB = renderBBCode(`[img]https://cdn.example.com/img.png?w=200&h=100[/img]`);
console.log("\n=== legit BBCode query-string URL ===");
console.log(legitBB);

// safeLinkHref protocol-relative check
const protoRel = renderModMarkdown(`[evil](//evil.example.com/steal)`);
console.log("\n=== protocol-relative link (should be '#', not treated as site-relative) ===");
console.log(protoRel);

// ReDoS timing re-check
for (const n of [2000, 4000, 5990]) {
  const input = "<img" + " ".repeat(n) + "x";
  const t0 = Date.now();
  renderModBody(input, "modrinth");
  console.log(`ReDoS check n=${n}: ${Date.now() - t0}ms`);
}

